import { useState } from 'react';

const INITIAL = [
  { id: 'a1', title: 'Arrival', year: 2016 },
  { id: 'p2', title: 'Past Lives', year: 2023 },
];

export default function App() {
  const [movies, setMovies] = useState(INITIAL);

  function addDune() {
    setMovies([{ id: 'd3', title: 'Dune: Part Two', year: 2024 }, ...movies]);
  }

  const newestFirst = movies.toSorted((a, b) => b.year - a.year);

  return (
    <main>
      <button onClick={addDune}>Add Dune: Part Two</button>
      <ul>
        {newestFirst.map((movie) => (
          <li key={movie.id}>
            <span>{movie.title} ({movie.year})</span>
            <input aria-label="Note" placeholder="Note" />
          </li>
        ))}
      </ul>
    </main>
  );
}
